"""t148 — et1 : l'Établi, etabli/aide.js en entier (lexique + pas à pas de l'aide) et etabli/etabli.js lignes 1 à 2400
(barre du bas, chronologie, ligne d'écart A/B, retour au 3D Studio, plaque et plan de plaque, imprimante, rangement,
mesure, surplombs, tranches, impression, orientation, rig, moteurs de jeu, matériaux, retour Blender, matières,
libellés des outils, assise).

Lexique : terme et phrase repris du guide anglais (docs/guide/en.html, ancres lex-<clé>), ramenés à la phrase courte de
l'écran ; les CLÉS de LEXIQUE ne changent pas. GARDÉ : les messages du serveur (`e.message`, `d.avertissement`,
`r.avertissement`, `refusDe`), les noms venus du disque (jobs, os, clips, matériaux, profils), les clés de granularité
et de champ (« maillage », « couleur »… comparées ou envoyées), les locales « fr-FR », les unités (Mo, Ko), et une
erreur de programmation (`mode de geste inconnu`) jamais montrée.
"""
from outils import L, S, X, H

PLAGES = {"etabli/aide.js": (1, 69), "etabli/etabli.js": (1, 2400)}

A = "etabli/aide.js"
E = "etabli/etabli.js"


def LX(ligne, cle, titre, texte, titre_en, texte_en, contexte=False):
    """Une entrée du LEXIQUE : titre et texte, chacun sa clé (contexte : terme du métier, sens propre à l'impression 3D)."""
    return [L(A, ligne, f'"{titre}"', f"etabli.et1_lex.{cle}_titre", titre, titre_en, contexte=contexte),
            L(A, ligne, f'"{texte}"', f"etabli.et1_lex.{cle}_texte", texte, texte_en)]


